// Serenity WAVETABLE - vector/native UI reconstruction based on the ten
// supplied reference screenshots. No raster screenshot is ever drawn.
// All artwork and widget geometry is generated by JUCE Graphics at runtime.
#include "PluginEditor.h"
#include <cmath>
#include <array>
#include <algorithm>

namespace {
using C=juce::Colour;
constexpr auto BG=0xff080d16u, PANEL=0xff1e293bu, PANE2=0xff263246u,
 STROKE=0xff36465au, DARK=0xff0b121du, TYPE=0xffd7dfecu,
 MUTE=0xff8d9bb0u, CYAN=0xff72dce9u, PURPLE=0xffac89f4u,
 GOLD=0xffd8b667u, SOFT=0xff162132u;
constexpr float pi=3.14159265358979323846f;
juce::String u(const char* s){return juce::String::fromUTF8(s);}
float clamp(float x,float a=0.f,float b=1.f){return juce::jlimit(a,b,x);}
struct Painter {
 juce::Graphics& g;
 SerenityAudioProcessor& dsp;
 bool fr;
 int selectedOsc;
 Painter(juce::Graphics& gg,SerenityAudioProcessor& dd,int osc):
  g(gg),dsp(dd),fr(dd.french()),selectedOsc(osc){}
 C c(juce::uint32 v){return C(v);}
 juce::String tr(const char* en,const char* french)const{
  return u(fr?french:en);
 }
 void rect(float x,float y,float w,float h,juce::uint32 colour){
  g.setColour(c(colour));g.fillRect(juce::Rectangle<float>(x,y,w,h));
 }
 void rr(float x,float y,float w,float h,float radius,juce::uint32 colour){
  g.setColour(c(colour));g.fillRoundedRectangle(x,y,w,h,radius);
 }
 void outline(float x,float y,float w,float h,float radius,
              juce::uint32 colour,float thickness=1.f){
  g.setColour(c(colour));g.drawRoundedRectangle(x,y,w,h,radius,thickness);
 }
 void line(float x1,float y1,float x2,float y2,juce::uint32 colour,float thick=1.f){
  g.setColour(c(colour));g.drawLine(x1,y1,x2,y2,thick);
 }
 void tx(const juce::String& str,float x,float y,float w,float h,int points=12,
         juce::uint32 colour=TYPE,bool bold=false,int justification=0){
  g.setColour(c(colour));
  g.setFont(juce::Font((float)points,bold?juce::Font::bold:juce::Font::plain));
  g.drawFittedText(str,juce::Rectangle<int>((int)x,(int)y,(int)w,(int)h),
    justification==1?juce::Justification::centred:
    justification==2?juce::Justification::centredRight:
    juce::Justification::centredLeft,1);
 }
 void tx(const char* str,float x,float y,float w,float h,int pts=12,
         juce::uint32 col=TYPE,bool bold=false,int j=0){
  tx(u(str),x,y,w,h,pts,col,bold,j);
 }
 void panel(float x,float y,float w,float h,const char* title,
            juce::uint32 accent=CYAN){
  g.setGradientFill(juce::ColourGradient(c(PANE2),x,y,c(PANEL),x+w,y+h,false));
  g.fillRoundedRectangle(x,y,w,h,8.f);
  outline(x,y,w,h,8.f,STROKE);
  line(x+2,y+28,x+w-2,y+28,0xff3b4a60u);
  // Reconstructed illuminated diamond, not a raster glyph.
  juce::Path diamond;
  diamond.startNewSubPath(x+15,y+9);
  diamond.lineTo(x+20,y+14);diamond.lineTo(x+15,y+19);
  diamond.lineTo(x+10,y+14);diamond.closeSubPath();
  g.setColour(c(accent));g.fillPath(diamond);
  tx(title,x+27,y+3,w-37,24,13,0xffc6d1e2u,true);
 }
 void grid(float x,float y,float w,float h,int cols=6,int rows=4){
  rr(x,y,w,h,5.f,DARK);
  outline(x,y,w,h,5.f,0xff3a4556u);
  for(int k=1;k<cols;k++)line(x+w*k/cols,y+2,x+w*k/cols,y+h-2,0xff1b2839u,.8f);
  for(int k=1;k<rows;k++)line(x+2,y+h*k/rows,x+w-2,y+h*k/rows,0xff1b2839u,.8f);
 }
 float val(int idx,float defaultValue=0.5f)const{
  if(idx<0||idx>=serenity::parameterCount)return defaultValue;
  const auto& sp=serenity::specs[(size_t)idx];
  return clamp((dsp.getValue(idx)-sp.lo)/std::max(.000001f,sp.hi-sp.lo));
 }
 juce::String value(int idx,int precision=2) const {
  return idx<0?juce::String("0.50"):juce::String(dsp.getValue(idx),precision);
 }
 void knob(float x,float y,float radius,const char* name,int idx=-1,
           juce::uint32 accent=CYAN,float fallback=.5f){
  const float v=val(idx,fallback);
  g.setColour(c(0xff0b1220u));g.fillEllipse(x-radius-3,y-radius-3,2*radius+6,2*radius+6);
  g.setColour(c(0xff526176u));g.drawEllipse(x-radius-2,y-radius-2,2*radius+4,2*radius+4,1.4f);
  g.setGradientFill(juce::ColourGradient(c(0xff49556cu),x-radius,y-radius,
                                          c(0xff111928u),x+radius,y+radius,true));
  g.fillEllipse(x-radius,y-radius,radius*2,radius*2);
  g.setColour(c(0xff152034u));g.drawEllipse(x-radius+4,y-radius+4,
                                               (radius-4)*2,(radius-4)*2,1.f);
  const float start=pi*.76f, end=start+pi*1.48f;
  juce::Path arc;arc.addCentredArc(x,y,radius+2,radius+2,0,start,start+(end-start)*v,true);
  g.setColour(c(accent));g.strokePath(arc,juce::PathStrokeType(3.2f));
  const float angle=start+(end-start)*v;
  line(x+std::sin(angle)*(radius-12),y-std::cos(angle)*(radius-12),
       x+std::sin(angle)*(radius-5),y-std::cos(angle)*(radius-5),0xffd9e5efu,2.f);
  tx(name,x-radius-26,y+radius+5,2*radius+52,19,10,MUTE,true,1);
  tx(idx>=0?value(idx):juce::String(fallback,2),
     x-radius-27,y+radius+22,2*radius+54,17,10,0xff8899b0u,false,1);
 }
 void miniKnob(float x,float y,const char* name,int idx=-1,float fallback=.5f,
               juce::uint32 accent=CYAN){
  knob(x,y,19.f,name,idx,accent,fallback);
 }
 void tab(float x,float y,float w,float h,const char* label,bool active,
          juce::uint32 accent=GOLD){
  rr(x,y,w,h,5.f,active?0xff47474bu:DARK);
  outline(x,y,w,h,5.f,active?accent:STROKE,active?1.5f:1.f);
  tx(label,x+5,y,w-10,h,12,active?accent:MUTE,true,1);
 }
 void button(float x,float y,float w,float h,const char* label,bool active=false,
             juce::uint32 accent=CYAN){
  rr(x,y,w,h,6.f,active?0xff314452u:DARK);
  outline(x,y,w,h,6.f,active?accent:STROKE);
  tx(label,x+3,y,w-6,h,11,active?accent:MUTE,true,1);
 }
 void select(float x,float y,float w,const char* title,const juce::String& selected,
             juce::uint32 accent=CYAN){
  tx(title,x,y,w,19,11,MUTE,true);
  rr(x,y+22,w,32,5.f,DARK);outline(x,y+22,w,32,5.f,STROKE);
  tx(selected,x+10,y+24,w-27,27,13,TYPE);
  juce::Path triangle;triangle.addTriangle(x+w-20,y+36,x+w-12,y+36,x+w-16,y+41);
  g.setColour(c(accent));g.fillPath(triangle);
 }
 void level(float x,float y,float w,float v,juce::uint32 accent=CYAN){
  rr(x,y,w,4,2,0xff0b101bu);
  rr(x,y,w*clamp(v),4,2,accent);
  rr(x+w*clamp(v)-4,y-5,8,15,3,0xff8ca0b7u);
 }
 void waveform(float x,float y,float w,float h,int shape,float phase=0.f,
               juce::uint32 color=CYAN,float amplitude=1.f,float frames=1.f){
  grid(x,y,w,h,4,2);
  juce::Path path;
  for(int i=0;i<=200;i++){
   const float t=(float)i/200.f,angle=2.f*pi*(t+phase);
   float v=0.f;
   switch(shape%8){
    case 0:v=std::sin(angle);break;
    case 1:v=.72f*std::sin(angle)+.16f*std::sin(2*angle)+.1f*std::sin(3*angle);break;
    case 2:v=2.f*(t-std::floor(t+.5f));break;
    case 3:v=std::tanh(6.f*std::sin(angle));break;
    case 4:v=std::sin(angle)+.2f*std::sin(7.f*angle);break;
    case 5:v=std::sin(2*angle)+.27f*std::sin(5*angle);break;
    case 6:v=std::sin(angle)*std::cos(5*angle);break;
    default:v=.7f*std::sin(angle)+.3f*std::cos(11*angle);break;
   }
   const float px=x+6+(w-12)*t,py=y+h*.5f-h*.38f*amplitude*v;
   if(i==0)path.startNewSubPath(px,py);else path.lineTo(px,py);
  }
  if(frames>1.f){g.setColour(c(color).withAlpha(.10f));g.strokePath(path,juce::PathStrokeType(5.f));}
  g.setColour(c(color));g.strokePath(path,juce::PathStrokeType(2.f));
 }
 void waves3d(float x,float y,float w,float h,int shape,float position){
  grid(x,y,w,h,7,5);
  for(int layer=7;layer>=0;layer--){
   const float off=(float)layer/7.f;
   juce::Path path;
   for(int k=0;k<=140;k++){
    const float t=(float)k/140.f,angle=2*pi*(t+off*.012f);
    float sample=std::sin(angle)+(.20f+off*.15f)*std::sin(2*angle);
    if(shape==3)sample=std::tanh(4.f*std::sin(angle));
    if(shape==2)sample=2.f*(t-.5f);
    float xx=x+18+t*(w-66)+off*29;
    float yy=y+h*.67f-layer*(h*.07f)-sample*(h*.145f);
    if(k==0)path.startNewSubPath(xx,yy);else path.lineTo(xx,yy);
   }
   const bool selected=std::abs((float)layer/7.f-position)<.10f;
   g.setColour(c(selected?0xffbadfeau:CYAN).withAlpha(selected?1.f:.35f+(.055f*layer)));
   g.strokePath(path,juce::PathStrokeType(selected?2.4f:1.5f));
  }
 }
 void graphFilter(float x,float y,float w,float h,float f1,float f2=-1.f){
  grid(x,y,w,h,10,6);
  juce::Path first,second;
  for(int i=0;i<=250;i++){
   const float t=(float)i/250;
   const float cutoff=clamp(f1);
   const float sigmoid=1.f/(1.f+std::exp(-(t-cutoff)*36.f));
   const float d=clamp(.5f+.04f- sigmoid*.6f,0.05f,.95f);
   float px=x+w*t,py=y+h*d;
   if(i==0)first.startNewSubPath(px,py);else first.lineTo(px,py);
   if(f2>=0.f) {
    const float d2=clamp(.55f+.02f-1.f/(1.f+std::exp(-(t-clamp(f2))*30.f))*.6f,.05f,.95f);
    if(i==0)second.startNewSubPath(px,y+h*d2);else second.lineTo(px,y+h*d2);
   }
  }
  g.setColour(c(CYAN));g.strokePath(first,juce::PathStrokeType(2.3f));
  if(f2>=0){g.setColour(c(PURPLE).withAlpha(.8f));
   const float dash[]={5.f,5.f};juce::Path dashed;
   juce::PathStrokeType(1.5f).createDashedStroke(dashed,second,dash,2);
   g.fillPath(dashed);}
 }
 void waveformSmall(float x,float y,float w,float h,int wave=0){
  waveform(x,y,w,h,wave,0.f,CYAN,.9f);
 }
 void header();
 void footer();
 void sources(float y=803.f);
 void oscillators();
 void editor();
 void filters();
 void modulation();
 void effects();
 void arpeggiator();
 void sequencer();
 void matrix();
 void presets();
 void settings();
};
} // namespace

void SerenityEditor::paintNativePage(juce::Graphics& g){
 juce::Graphics::ScopedSaveState saved(g);
 g.addTransform(juce::AffineTransform::scale((float)getWidth()/1492.f,(float)getHeight()/991.f));
 Painter p(g,synth,selectedOsc);
 g.fillAll(juce::Colour(BG));
 p.header();
 switch(tab){
  case 0:p.oscillators();break;
  case 1:p.editor();break;
  case 2:p.filters();break;
  case 3:p.modulation();break;
  case 4:p.effects();break;
  case 5:p.arpeggiator();break;
  case 6:p.sequencer();break;
  case 7:p.matrix();break;
  case 8:p.presets();break;
  case 9:p.settings();break;
 }
 p.footer();
}
